// Direct call (POSIX/BSD)
int page_size_bytes = getpagesize();

// POSIX/SUS recommended alternative:
// Requires inclusion of <unistd.h>
long sysconf_size = sysconf(_SC_PAGESIZE);

// Typical result: 4096 (4 KiB) or 16384 (16 KiB)

// Used for calculating aligned mapping sizes:
size_t num_pages = 5;
size_t required_map_size = page_size_bytes * num_pages;

/* 
 * Required_map_size must be a multiple 
 * of the page size for mmap(2) 
 */
